Section Run.
Variables (K : TSet) (R : bvmap 5 word) (M : mem) (model : Model) (LBX : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit)
          (V2 cls r o y fb : Z) (len : nat) (v0 : Z).
Local Notation sp := (V2 + cls).
Local Notation spc := (V2 - 160).
Local Notation W := ([(o, 32)] : list L5.range).
Local Notation BX0 := ([] : list (Z * Z)).
Local Notation SCR := (PMSPA.pm_scr PQATSS.ADD_H).
Hypothesis Hcls : cls = 0 \/ cls = 16.
Hypothesis V32 : V2 mod 32 = 0.
Hypothesis HH : ri_inv HI (BX0 ++ LBX) FF LK cr Aw M (vml_of model).
Hypothesis AM : L5CA.amodel_ok Aw model.
Hypothesis K0 : K [].
Hypothesis ENT : PMSPA.entryA AD L ar R M sp r PQATSS.ADD_H.
Hypothesis FRM : PGSA.ffroomB PQRA.FCM PQATSS.ADD_H FF LK.
Hypothesis FRS : PMSPA.ffrsA FF sp.
Hypothesis A10 : getr R (reg 10) = Z_to_bv 64 o.
Hypothesis A11 : getr R (reg 11) = Z_to_bv 64 y.
Hypothesis Hy : 0 <= y < 2 ^ 64.
Hypothesis AO : PMSPA.aobjA FF o 32.
Hypothesis O8 : o mod 8 = 0.
Hypothesis ACC : PMSPA.accA M o 32.
Hypothesis BIN : PQATSS.binl_at RSEGS M o fb len v0 0.
Hypothesis Hlen : (len <= 1)%nat.
Hypothesis Hlen0 : len = 0%nat -> v0 = 0.
Hypothesis Tb1 : Z.testbit fb 1 = false.
Hypothesis BASE : PMSTA.base_okA RSEGS AD M.
Hypothesis KONT : forall (fx' : FPState) (R' : bvmap 5 word) (M' : mem) (model' : Model) (LK' : list fframe) (w0 w1 : Z),
    regs_preserved R R' -> getr R' (reg 10) = Z_to_bv 64 o ->
    w0 + 2 ^ 64 * w1 = v0 + y -> PQATSS.binl_at RSEGS M' o fb (PQATSS.wlen w0 w1) w0 w1 ->
    L5CA.ahpres L ar LBX FF sp SCR W M M' ->
    model_rt model model' -> incl LK' LK -> L5CA.amodel_ok Aw model' ->
    ri_inv HI LBX FF LK' cr Aw M' (vml_of model') ->
    srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' r M' model') K.

Local Notation OWN := (own12 sp R).
Local Notation OC := (ocell12 sp).

