Lemma sum2_ok v0 v1 y : 0 <= v0 < 2 ^ 64 -> 0 <= v1 < 2 ^ 64 -> 0 <= y < 2 ^ 64 -> v0 + 2 ^ 64 * v1 + y < 2 ^ 128 ->
  let w0 := (v0 + y) mod 2 ^ 64 in let c := (v0 + y) / 2 ^ 64 in
  w0 + 2 ^ 64 * (v1 + c) = v0 + 2 ^ 64 * v1 + y /\ 0 <= c <= 1 /\ (c = 1 <-> w0 < v0) /\ (c = 1 -> v1 + 1 < 2 ^ 64) /\ 0 <= w0 < 2 ^ 64.
Proof.
