Lemma mprod2_ok v0 v1 : 0 <= v0 < 2 ^ 64 -> 0 <= v1 < 2 ^ 64 -> 10 * (v0 + 2 ^ 64 * v1) < 2 ^ 128 ->
  let w0 := mlo10 v0 in let w1 := (mlo10 v1 + mhi10 v0) mod 2 ^ 64 in
  let c := (mhi10 v1 + (if (mlo10 v1 + mhi10 v0) mod 2 ^ 64 <? mlo10 v1 then 1 else 0)) mod 2 ^ 64 in
  w0 + 2 ^ 64 * w1 = 10 * (v0 + 2 ^ 64 * v1) /\ c = 0 /\ 0 <= w0 < 2 ^ 64 /\ 0 <= w1 < 2 ^ 64.
Proof.
