(* [comment removed for export] *)
Lemma cback M1 model1 LK1 (M2 : mem) model2 LK2 :
  mm M1 model1 LK1 -> L5CA.ahpres L ar LB FF spc SCR3 W M1 M2 -> ri_inv HI LB FF LK2 cr Aw M2 (vml_of model2) -> L5CA.amodel_ok Aw model2 ->
  model_rt model1 model2 -> incl LK2 LK1 ->
