Section WithHeap.
Context {SCFG_P : ScfgP}.
Variables (L : asan_layout) (ar : asan_run) (C : asan_statics_cells) (HI : asan_iface).
Hypothesis LY : PMA.layout L C.
Hypothesis HIok : HAJ.asan_iface_okR L ar C SCFG HI.
Let LYa := PMA.ly_as0 L C LY.
Let SHL := PQATSHL.shl0_ok L ar C HI LY HIok.

Section Run.
Variables (K : TSet) (R : bvmap 5 word) (M : mem) (model : Model) (LB : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit)
          (sp r th o y ax fbd fbn : Z) (d0 d1 n0 n1 : Z).
Local Notation W := ([(o, 32); (y, 32); (ax, 4)] : list L5.range).
Local Notation W1 := ([(o, 32)] : list L5.range).
Local Notation W2 := ([(y, 32)] : list L5.range).
Local Notation SCR := (PMSPA.pm_scr PQATSC4.NORM_H).
Local Notation SCR3 := (PMSPA.pm_scr 3).
Local Notation spc := (sp - 80).
Hypothesis HH : ri_inv HI LB FF LK cr Aw M (vml_of model).
Hypothesis AM : L5CA.amodel_ok Aw model.
Hypothesis K0 : K [].
Hypothesis ENT : PMSPA.entryA AD L ar R M sp r PQATSC4.NORM_H.
Hypothesis FRM : PGSA.ffroomB PQRA.FCM PQATSC4.NORM_H FF LK.
Hypothesis FRS : PMSPA.ffrsA FF sp.
Hypothesis SP16 : sp mod 16 = 0.
Hypothesis A10 : getr R (reg 10) = Z_to_bv 64 th.
Hypothesis A11 : getr R (reg 11) = Z_to_bv 64 o.
Hypothesis A12 : getr R (reg 12) = Z_to_bv 64 y.
Hypothesis A13 : getr R (reg 13) = Z_to_bv 64 ax.
Hypothesis AO : PMSPA.aobjA FF o 32.
Hypothesis O8 : o mod 8 = 0.
Hypothesis ACC : PMSPA.accA M o 32.
Hypothesis BIN : PQATSS.binl_at RSEGS M o fbd 1%nat d0 d1.
Hypothesis D63 : 2 ^ 63 <= d0.
Hypothesis AOy : PMSPA.aobjA FF y 32.
Hypothesis Y8 : y mod 8 = 0.
Hypothesis ACCy : PMSPA.accA M y 32.
Hypothesis BINy : PQATSS.binl_at RSEGS M y fbn 2%nat n0 n1.
Hypothesis N1 : 1 <= n1.
Hypothesis APART : o + 32 <= y \/ y + 32 <= o.
Hypothesis AXLO : sp <= ax - 4.
Hypothesis AXHI : ax + 4 <= ar_sptop ar.
Hypothesis AX8 : ax mod 8 = 4.
Hypothesis SHZX : shadow_zero M (ax - 4) 1.
Hypothesis DEFX : L5.defined M (ax - 4) 8.
Hypothesis BASE : PMSTA.base_okA RSEGS AD M.
Hypothesis KONT : forall (fx' : FPState) (R' : bvmap 5 word) (M' : mem) (model' : Model) (LK' : list fframe),
    regs_preserved R R' -> getr R' (reg 10) = Z_to_bv 64 0 ->
    PQATSS.binl_at RSEGS M' o fbd 1%nat d0 d1 -> PQATSS.binl_at RSEGS M' y fbn 2%nat n0 n1 -> L5.u32_at RSEGS M' ax 0 -> shadow_zero M' (ax - 4) 1 ->
    L5CA.ahpres L ar LB FF sp SCR W M M' ->
    model_rt model model' -> incl LK' LK -> L5CA.amodel_ok Aw model' ->
    ri_inv HI LB FF LK' cr Aw M' (vml_of model') ->
    srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' r M' model') K.

