Definition assign0d_specG (pc h : Z) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LB : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (sp r d s fb fbs : Z) (lend : nat) (p d0 d1 s0 s1 : Z),
    ri_inv HI LB FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] ->
    PMSPA.entryA A L ar R M sp r h -> PGSA.ffroomB PQRA.FCM h FF LK -> PMSPA.ffrsA FF sp -> sp mod 16 = 0 ->
    getr R (reg 10) = Z_to_bv 64 d -> getr R (reg 11) = Z_to_bv 64 s ->
    PMSPA.aobjA FF d 32 -> d mod 8 = 0 -> PMSPA.accA M d 32 -> PQATSW2.bdyn_at segs M d fb lend p d0 d1 -> (lend <= 2)%nat -> In (p, 64) LB ->
    PMSPA.aobjA FF s 32 -> s mod 8 = 0 -> PMSPA.accA M s 32 -> PQATSS.binl_at segs M s fbs 0%nat s0 s1 ->
    (d + 32 <= s \/ s + 32 <= d) ->
    PMSTA.base_okA segs A M ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe),
        regs_preserved R R' -> getr R' (reg 10) = Z_to_bv 64 d ->
        PQATSW2.bdyn_at segs M' d fb 0%nat p d0 d1 -> PQATSS.binl_at segs M' s fbs 0%nat s0 s1 ->
        L5CA.ahpres L ar LB FF sp (PMSPA.pm_scr h) [(d, 32)] M M' ->
        model_rt model model' -> incl LK' LK -> L5CA.amodel_ok Aw model' ->
        ri_inv HI LB FF LK' cr Aw M' (vml_of model') ->
        srealizes segs SCFG (@PMSPA.cfg segs fx' R' r M' model') K) ->
    srealizes segs SCFG (@PMSPA.cfg segs fx R pc M model) K.
End Stmt.
