Section WithHeap.
Context {SCFG_P : ScfgP}.
Variables (L : asan_layout) (ar : asan_run) (C : asan_statics_cells) (HI : asan_iface).
Hypothesis LY : PMA.layout L C.
Hypothesis HIok : HAJ.asan_iface_okR L ar C SCFG HI.
Let LYa := PMA.ly_as0 L C LY.
Let RZ := PQATRZ.resizeI_ok L ar C HI LY HIok.
Let RZL := PQATRZL.resizeL_ok L ar C HI LY HIok.
Let RZD := PQATRZDD.resizeDd_ok L ar C HI LY HIok.

(* [comment removed for export] *)
Lemma amcpy LB FF LK cr Aw sp scr fr o sz (fx0 : FPState) Ra Ma modela Kc d n q (bs : list byte) ra :
  L5CA.aobj FF o sz -> 0 <= d -> d + n <= sz -> 0 < n <= 96 ->
  ri_inv HI LB FF LK cr Aw Ma (vml_of modela) -> L5CA.amodel_ok Aw modela -> L5CA.astk ar Ma sp scr -> PMSPA.accA Ma o sz -> L5.defined Ma o sz ->
  0 <= fr -> fr + 2560 <= scr -> (sp - fr) mod 16 = 0 ->
  getr Ra (reg 10) = Z_to_bv 64 (o + d) -> getr Ra (reg 11) = Z_to_bv 64 q -> getr Ra (reg 12) = Z_to_bv 64 n -> getr Ra (reg 4) = Z_to_bv 64 (hl_tp L) ->
  getr Ra (reg 1) = Z_to_bv 64 ra -> ra mod 2 = 0 -> 0 <= ra < 2 ^ 64 -> getr Ra (reg 2) = Z_to_bv 64 (sp - fr) -> Kc [] ->
  PMSPA.accA Ma q n -> 0 <= q -> q + n <= 2 ^ 47 -> app_rng ar q n -> (forall i, 0 <= i < n -> aclient L ar LB FF (sp - fr) 2560 (q + i)) ->
  rdn RSEGS Ma (Z_to_bv 64 q) (Z.to_nat n) = Some bs -> (o + d + n <= q \/ q + n <= o + d) ->
  (forall Rb Mb modelb, getr Rb (reg 10) = Z_to_bv 64 (o + d) -> regs_preserved Ra Rb ->
     (forall i, 0 <= i < n -> exists v, (nth_error bs (Z.to_nat i) = Some (Z_to_bv 8 v) /\ 0 <= v < 256) /\ byte_at Mb (o + d + i) v) ->
     (forall a, 0 <= a < 2 ^ 64 -> aclient L ar LB FF (sp - fr) 2560 a -> ~ (o + d <= a < o + d + n) -> Mb (Z_to_bv 64 a) = Ma (Z_to_bv 64 a)) ->
     (forall a, sp - fr - 2560 <= a < sp - fr -> Mb (Z_to_bv 64 a) <> None) ->
     L5.defined Mb (o + d) n -> model_rt modela modelb -> L5CA.amodel_ok Aw modelb -> ri_inv HI LB FF LK cr Aw Mb (vml_of modelb) ->
     srealizes RSEGS SCFG (PMSPA.cfg RSEGS (fx:=fx0) Rb ra Mb modelb) Kc) ->
  srealizes RSEGS SCFG (PMSPA.cfg RSEGS (fx:=fx0) Ra 0x7ebbc Ma modela) Kc.
Proof.
