(* [comment removed for export] *)
Lemma mm_obj M2 model2 LK2 (M3 : mem) model3 (lo n : Z) :
  mm M2 model2 LK2 -> ri_inv HI LB FF LK2 cr Aw M3 (vml_of model3) -> L5CA.amodel_ok Aw model3 -> model_rt model2 model3 -> mem_grows M2 M3 ->
  (forall a, 0 <= a < 2 ^ 64 -> ~ (o + lo <= a < o + lo + n) -> M3 (Z_to_bv 64 a) = M2 (Z_to_bv 64 a)) -> 0 <= lo -> lo + n <= 32 ->
