Hypothesis INP : In (pn, 64) LB.
Hypothesis N1 : 1 <= n1.
Hypothesis APART : o + 32 <= y \/ y + 32 <= o.
Hypothesis AXLO : sp <= ax - 4.
Hypothesis AXHI : ax + 4 <= ar_sptop ar.
Hypothesis AX8 : ax mod 8 = 4.
Hypothesis SHZX : shadow_zero M (ax - 4) 1.
Hypothesis DEFX : L5.defined M (ax - 4) 8.
Hypothesis BASE : PMSTA.base_okA RSEGS AD M.
Hypothesis KONT : forall (fx' : FPState) (R' : bvmap 5 word) (M' : mem) (model' : Model) (LK' : list fframe),
    regs_preserved R R' -> getr R' (reg 10) = Z_to_bv 64 0 ->
    PQATSS.binl_at RSEGS M' o fbd 1%nat d0 d1 -> PQATSW2.bdyn_at RSEGS M' y fbn 2%nat pn n0 n1 -> L5.u32_at RSEGS M' ax 0 -> shadow_zero M' (ax - 4) 1 ->
    L5CA.ahpres L ar LB FF sp SCR W M M' ->
