  getr R5 (reg 8) = Z_to_bv 64 (bvu (getr R (reg 8))) -> getr R5 (reg 9) = Z_to_bv 64 (bvu (getr R (reg 9))) -> getr R5 (reg 10) = Z_to_bv 64 0 ->
