Lemma TAIL2 M2 model2 LK2 (fx2 : FPState) (R2 : bvmap 5 word) :
  mm M2 model2 LK2 -> PQATSS.binl_at RSEGS M2 o fbd 1%nat d0 d1 -> ydyn M2 -> L5.u32_at RSEGS M2 (ax - 4 + 4) 0 ->
  getr R2 (reg 2) = Z_to_bv 64 spc -> getr R2 (reg 8) = Z_to_bv 64 o -> getr R2 (reg 9) = Z_to_bv 64 y ->
  getr R2 (reg 21) = Z_to_bv 64 (o / 8 + 2147450880) -> getr R2 (reg 23) = Z_to_bv 64 0 ->
  (forall k, In k [3; 4; 25; 26; 27]%nat -> getr R2 (reg k) = getr R (reg k)) ->
